'use strict';
// Passenger starts app.js directly. The Next build may be rooted at apps/web.
// Keep NODE_ENV production, and use the server entry generated by Next.js.
process.env.NODE_ENV = 'production';
const { existsSync } = require('node:fs');
if (existsSync(__dirname + '/server.js')) require('./server.js');
else if (existsSync(__dirname + '/apps/web/server.js')) require('./apps/web/server.js');
else throw new Error('IMTAQ standalone server is missing. Restore previous deployment.');
